// Manual dev script (task 005-3, R-37; same "committed-.ts-literal, regenerated by hand" pattern
// as scripts/record-fixture.mjs) — NOT part of CI (nothing in .github/workflows/ci.yml invokes
// it, and no test imports it: enforced by this task's own acceptance grep).
//
// Reads the per-operation `x-credit-cost` extension (`{free, pro}`) out of the committed
// `docs/onchain-analytics/raw/nansen-openapi-2026-07-23.json` for EXACTLY the ~8 endpoints M2's
// three capabilities (`smart-money.flows`, `entity.labels`, `token.risk`) actually call — NOT all
// 74 operations in the 630KB spec (out of scope, TASK.md §4) — plus the ONE
// `x-credit-cost-variants['premium_labels=true']` surcharge `POST /api/v1/tgm/holders` declares
// (code review round 2 fix — this used to be a hand-maintained `150` literal in cost-of.ts, which
// could drift silently against the spec with zero diff; it is now regenerated here instead) — and
// writes the committed, git-diff'able literal `packages/core/src/adapters/nansen/cost-table.ts`.
// This script itself reads the whole spec file into Node's memory (that's fine — it's Node doing
// a one-off dev-time read, not context an agent has to load); the task's own "read the spec point
// wise" instruction is about *reviewing this task*, not about how the script itself is implemented.
//
// Re-run after a vendor spec refresh: `node packages/core/scripts/generate-nansen-cost-table.mjs`
// — regeneration is BYTE-IDEMPOTENT for an unchanged spec with NO extra formatting pass required
// (code review round 2 fix: the source string this script emits is built directly in the exact
// Prettier-conformant shape — single-quoted keys, `.prettierrc`'s `singleQuote: true` — instead of
// via `JSON.stringify`, which emitted double-quoted keys that only LOOKED stable because a
// `prettier --write` pass silently normalized them back on the very first run; a bare re-run used
// to flip all 8 lines' quote style with zero substantive change, burying a real price change in
// quote-flip noise). Verify with: generate → `md5`, generate again → `md5` identical, WITHOUT
// running prettier in between (this task's own Phase 1 acceptance: `git diff --stat` on the
// output file is empty after a repeat run). Any REAL vendor price drift the next time this is
// re-run shows up as a normal, reviewable git diff on `cost-table.ts` — never silently, and never
// buried in reformatting noise.
//
// Usage: node packages/core/scripts/generate-nansen-cost-table.mjs

import { readFileSync, writeFileSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const scriptDir = path.dirname(fileURLToPath(import.meta.url));
const packageRoot = path.resolve(scriptDir, '..');
const repoRoot = path.resolve(packageRoot, '..', '..');
const specPath = path.resolve(
  repoRoot,
  'docs/onchain-analytics/raw/nansen-openapi-2026-07-23.json',
);
const outPath = path.resolve(packageRoot, 'src/adapters/nansen/cost-table.ts');

// Exactly the ~8 endpoints M2's three capabilities call (system-architecture.md §3.2 "Cost-table
// generation", task 005-3's own "Cost-таблица — ровно ~8 эндпоинтов" section) — the hand-picked
// capability→endpoint map itself lives in cost-of.ts, not here; this list only decides which
// spec operations get a table entry at all.
const ENDPOINTS = [
  { method: 'GET', path: '/api/v1/account' },
  { method: 'POST', path: '/api/v1/smart-money/netflow' },
  { method: 'POST', path: '/api/v1/tgm/holders' },
  { method: 'POST', path: '/api/v1/search/general' },
  { method: 'POST', path: '/api/v1/search/entity-name' },
  { method: 'POST', path: '/api/v1/profiler/address/labels' },
  { method: 'POST', path: '/api/v1/tgm/indicators' },
  { method: 'POST', path: '/api/v1/tgm/token-information' },
];

// The one `x-credit-cost-variants` surcharge cost-of.ts's premium-labels branch needs — lives on
// this SAME operation's spec entry, under a DIFFERENT extension key than the base `x-credit-cost`
// table above (`x-credit-cost-variants['premium_labels=true']` — spec only declares a `pro`
// price for this variant, no `free`; cost-of.ts is the one that decides to apply it to both plans
// conservatively, this script only extracts the raw spec-documented number).
const PREMIUM_LABELS_VARIANT = {
  method: 'POST',
  path: '/api/v1/tgm/holders',
  variantKey: 'premium_labels=true',
};

function fail(message) {
  console.error(`generate-nansen-cost-table: FAIL: ${message}`);
  process.exitCode = 1;
}

/** Emits `str` as a Prettier-conformant (`.prettierrc`'s `singleQuote: true`) single-quoted TS
 * string literal — NOT `JSON.stringify` (which always double-quotes), so this generator's raw
 * output needs zero `prettier --write` pass to already be byte-idempotent (code review round 2
 * fix). None of this script's own keys ever contain a `'` or `\`, but this still escapes both
 * defensively rather than assuming that stays true forever. */
function singleQuote(str) {
  return `'${str.replace(/\\/g, '\\\\').replace(/'/g, "\\'")}'`;
}

function main() {
  let spec;
  try {
    spec = JSON.parse(readFileSync(specPath, 'utf8'));
  } catch (error) {
    fail(`could not read/parse ${specPath}: ${error instanceof Error ? error.message : error}`);
    return;
  }

  const entries = [];
  for (const { method, path: opPath } of ENDPOINTS) {
    const operation = spec.paths?.[opPath]?.[method.toLowerCase()];
    const cost = operation?.['x-credit-cost'];
    if (!cost || typeof cost.free !== 'number' || typeof cost.pro !== 'number') {
      fail(`missing/invalid x-credit-cost for ${method} ${opPath} in ${specPath}`);
      return;
    }
    entries.push({ key: `${method} ${opPath}`, free: cost.free, pro: cost.pro });
  }

  const premiumOperation =
    spec.paths?.[PREMIUM_LABELS_VARIANT.path]?.[PREMIUM_LABELS_VARIANT.method.toLowerCase()];
  const premiumCost =
    premiumOperation?.['x-credit-cost-variants']?.[PREMIUM_LABELS_VARIANT.variantKey]?.pro;
  if (typeof premiumCost !== 'number') {
    fail(
      `missing/invalid x-credit-cost-variants['${PREMIUM_LABELS_VARIANT.variantKey}'].pro for ` +
        `${PREMIUM_LABELS_VARIANT.method} ${PREMIUM_LABELS_VARIANT.path} in ${specPath}`,
    );
    return;
  }

  const tableLines = entries
    .map(({ key, free, pro }) => `  ${singleQuote(key)}: { free: ${free}, pro: ${pro} },`)
    .join('\n');

  const contents = `// GENERATED by packages/core/scripts/generate-nansen-cost-table.mjs — DO NOT EDIT BY HAND.
// Source: docs/onchain-analytics/raw/nansen-openapi-2026-07-23.json's per-operation
// \`x-credit-cost\` (+ \`x-credit-cost-variants\`, below) extensions (system-architecture.md §3.2
// "Cost-table generation", task 005-3). Re-run
// \`node packages/core/scripts/generate-nansen-cost-table.mjs\` after a vendor spec refresh — a bare
// re-run is byte-idempotent (no \`prettier --write\` needed), so the diff IS the vendor price-drift
// signal (a committed, git-diff'able literal, never a runtime JSON parse of the 630KB spec).

/**
 * \`(method+path) -> {free, pro}\` credit cost. Exactly the ~8 endpoints M2's three capabilities
 * (\`smart-money.flows\`, \`entity.labels\`, \`token.risk\`) actually call — NOT all 74 operations in
 * the spec (out of scope, TASK.md §4). \`costOf()\` (cost-of.ts) looks keys up here; a key absent
 * from this table (future capability/endpoint drift) MUST resolve to
 * \`Number.POSITIVE_INFINITY\`, never \`0\` — fail-closed, R-37 MIN-3.
 */
export const NANSEN_COST_TABLE: Readonly<Record<string, { free: number; pro: number }>> = {
${tableLines}
};

/**
 * Flat per-call surcharge (credits) when a request sets \`premium_labels: true\` on
 * \`POST /api/v1/tgm/holders\` — sourced from the SAME committed spec's
 * \`x-credit-cost-variants['${PREMIUM_LABELS_VARIANT.variantKey}']\` extension on that operation
 * (the spec states ONLY a \`pro\` price for this variant; \`cost-of.ts\` applies it to BOTH plans
 * conservatively — see that file's own docstring for why). Regenerated here, not hand-maintained
 * (code review round 2 fix), so a future vendor change to this surcharge shows up as an ordinary
 * diff on THIS file instead of staying silently stale in \`cost-of.ts\`.
 */
export const NANSEN_PREMIUM_LABELS_COST = ${premiumCost};
`;

  writeFileSync(outPath, contents);
  console.log(`generate-nansen-cost-table: OK: wrote ${outPath}`);
}

main();
